<?php
require __DIR__.'/../includes/bootstrap.php';
$raw=file_get_contents('php://input');$body=json_decode($raw,true)?:[];$dataId=(string)($_GET['data.id']??$_GET['data_id']??($body['data']['id']??''));$type=$_GET['type']??($body['type']??'');
$signature=$_SERVER['HTTP_X_SIGNATURE']??'';$requestId=$_SERVER['HTTP_X_REQUEST_ID']??'';$secret=integrations_config()['mercado_pago']['webhook_secret'];
if($secret && !mp_validate_webhook($signature,$requestId,$dataId)){http_response_code(401);exit('invalid signature');}
if($type==='payment' && $dataId){$remote=mp_get_payment($dataId);if($remote['ok']){$d=$remote['data'];$external=(string)($d['external_reference']??'');$statusMap=['approved'=>'aprovado','pending'=>'pendente','in_process'=>'pendente','rejected'=>'rejeitado','cancelled'=>'cancelado','refunded'=>'reembolsado'];$status=$statusMap[$d['status']??'']??'pendente';$st=db()->prepare('SELECT * FROM payments WHERE id=? OR provider_payment_id=? LIMIT 1');$st->execute([(int)$external,$dataId]);$payment=$st->fetch();if($payment){db()->prepare('UPDATE payments SET provider_payment_id=?,status=?,paid_at=IF(?="aprovado",NOW(),paid_at) WHERE id=?')->execute([$dataId,$status,$status,$payment['id']]);db()->prepare('INSERT INTO payment_events(payment_id,provider_event_id,event_type,payload) VALUES (?,?,?,?)')->execute([$payment['id'],(string)($body['id']??''),(string)($body['action']??$type),json_encode($body)]);if($status==='aprovado'){if($payment['client_package_id'])db()->prepare("UPDATE client_packages SET status='ativo' WHERE id=?")->execute([$payment['client_package_id']]);if($payment['appointment_id'])db()->prepare("UPDATE appointments SET status='confirmado',confirmed_at=COALESCE(confirmed_at,NOW()) WHERE id=?")->execute([$payment['appointment_id']]);$exists=db()->prepare('SELECT id FROM finance_transactions WHERE payment_id=?');$exists->execute([$payment['id']]);if(!$exists->fetchColumn())db()->prepare("INSERT INTO finance_transactions(client_id,payment_id,type,category,description,amount,paid_date,status,payment_method) VALUES (?,?, 'receita','Pagamento','Recebimento Mercado Pago',?,CURDATE(),'pago','Mercado Pago')")->execute([$payment['client_id'],$payment['id'],$payment['amount']]);}}}}
